#requires -Version 5.1
[CmdletBinding()]param([string]$InstallRoot=(Join-Path $env:ProgramFiles 'Naide\LevelManager'),[string]$DataRoot=(Join-Path $env:ProgramData 'Naide\LevelManager'),[string]$ServiceName='Naide.LevelManager',[ValidateRange(1024,65535)][int]$Port=8780,[switch]$PrepareOnly)
$ErrorActionPreference='Stop'
if($PSVersionTable.PSEdition -eq 'Desktop'){$env:PSModulePath=Join-Path $PSHOME 'Modules'}
[Console]::OutputEncoding=New-Object Text.UTF8Encoding($false)
$businessLock=$null
Add-Type -AssemblyName System.Windows.Forms
function Require-PlainPath([string]$Value){$full=[IO.Path]::GetFullPath($Value);if($full -eq [IO.Path]::GetPathRoot($full)){throw '安装或业务目录不能是磁盘根目录'};$part=$full;while($part){if((Test-Path -LiteralPath $part) -and ((Get-Item -LiteralPath $part -Force).Attributes -band [IO.FileAttributes]::ReparsePoint)){throw '安装或数据路径不能包含重解析链接'};$parent=[IO.Directory]::GetParent($part);if($null -eq $parent){break};$part=$parent.FullName};return $full}
function Paths-Overlap([string]$Left,[string]$Right){return $Left.Equals($Right,[StringComparison]::OrdinalIgnoreCase) -or $Left.StartsWith($Right.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase) -or $Right.StartsWith($Left.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)}
function Protect-ServiceData([string]$Path){New-Item -ItemType Directory -Path $Path -Force|Out-Null;$acl=New-Object Security.AccessControl.DirectorySecurity;$acl.SetAccessRuleProtection($true,$false);foreach($sid in @('S-1-5-18','S-1-5-32-544')){$rule=New-Object Security.AccessControl.FileSystemAccessRule((New-Object Security.Principal.SecurityIdentifier($sid)),'FullControl','ContainerInherit,ObjectInherit','None','Allow');$acl.AddAccessRule($rule)};Set-Acl -LiteralPath $Path -AclObject $acl}
try{
 $identity=[Security.Principal.WindowsIdentity]::GetCurrent();$principal=New-Object Security.Principal.WindowsPrincipal($identity);if(!$PrepareOnly -and !$principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw '请右键以管理员身份运行安装.cmd，或使用管理员PowerShell'}
 if(![Environment]::Is64BitOperatingSystem -or ![Environment]::Is64BitProcess){throw '本包适用于64位Windows，请使用64位PowerShell'};if($ServiceName -notmatch '^Naide\.LevelManager(?:\.QA\.[a-zA-Z0-9]+)?$'){throw '服务名称无效'}
 $package=[IO.Path]::GetFullPath($PSScriptRoot);$InstallRoot=Require-PlainPath $InstallRoot;$DataRoot=Require-PlainPath $DataRoot;$authorizationRoot=Require-PlainPath ($DataRoot+'.authorization');$manifest=Get-Content -LiteralPath (Join-Path $package 'package-manifest.json') -Raw -Encoding UTF8|ConvertFrom-Json;if($manifest.productId -ne 'Naide.LevelManager.2026'){throw '安装包产品标识无效'}
 foreach($file in $manifest.files){$source=[IO.Path]::GetFullPath((Join-Path $package $file.path));if(!$source.StartsWith($package+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw '安装包文件路径越界'};if(!(Test-Path -LiteralPath $source -PathType Leaf) -or (Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash -ne $file.sha256){throw ('安装包文件校验失败：'+$file.path)}}
 if($manifest.version -notmatch '^[a-zA-Z0-9][a-zA-Z0-9.+-]{0,63}$'){throw '安装包版本格式无效'}
 foreach($pair in @(@($InstallRoot,$DataRoot),@($InstallRoot,$authorizationRoot),@($InstallRoot,$package),@($DataRoot,$package),@($authorizationRoot,$package))){if(Paths-Overlap $pair[0] $pair[1]){throw '安装程序、业务数据、授权保护及解压目录必须彼此独立，不能互相包含'}}
 $service=Get-Service -Name $ServiceName -ErrorAction SilentlyContinue;if($service -and $service.Status -ne 'Stopped'){throw '已有后台服务正在运行。请先结束作业、核对浮子状态并停止服务，再安装升级；安装程序不会强行停止服务'}
 if($service){$existingNative=Get-CimInstance Win32_Service -Filter ("Name='"+$ServiceName+"'");$match=[regex]::Match($existingNative.PathName,'--data-root\s+"([^"]+)"');if(!$match.Success -or !(Require-PlainPath $match.Groups[1].Value).Equals($DataRoot,[StringComparison]::OrdinalIgnoreCase)){throw '本次数据目录与原服务不一致，或无法核实原目录。请沿用原服务数据目录；本安装程序不自动迁移业务数据'}}
 $lockPath=Join-Path $DataRoot 'service.lock';if(Test-Path -LiteralPath $lockPath){$businessLock=[IO.File]::Open($lockPath,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)}
 $listener=New-Object Net.Sockets.TcpListener([Net.IPAddress]::Loopback,$Port);try{$listener.Start()}finally{$listener.Stop()}
 $plan=[PSCustomObject]@{Product=$manifest.productId;Version=$manifest.version;InstallRoot=$InstallRoot;DataRoot=$DataRoot;AuthorizationRoot=$authorizationRoot;ServiceName=$ServiceName;ServerUrl=('http://127.0.0.1:'+ $Port +'/');FilesChecked=@($manifest.files).Count;FreshInstallationStartsAcquisition=$false;ConfiguredStartupPolicyPreserved=$true}
 if($PrepareOnly){$plan|ConvertTo-Json;return}
 if([Windows.Forms.MessageBox]::Show('将安装中文联调测试版后台和桌面画面，默认只允许本机访问。业务数据与授权独立保存。必要时安装微软WebView2离线运行环境；其许可条款见随包说明。已有数据不会删除。是否继续？','液位管理系统安装','YesNo','Question') -ne 'Yes'){return}
 $versionRoot=Join-Path (Join-Path $InstallRoot 'versions') ($manifest.version+'-'+[DateTime]::UtcNow.ToString('yyyyMMddHHmmss')+'-'+[guid]::NewGuid().ToString('N').Substring(0,8));New-Item -ItemType Directory -Path $versionRoot -Force|Out-Null;Copy-Item -LiteralPath (Join-Path $package 'app') -Destination $versionRoot -Recurse;Copy-Item -LiteralPath (Join-Path $package 'docs') -Destination $versionRoot -Recurse
 Protect-ServiceData $DataRoot;Protect-ServiceData $authorizationRoot
 $runtimePath=Join-Path ${env:ProgramFiles(x86)} 'Microsoft\EdgeWebView\Application';$runtimeInstalled=@(Get-ChildItem -LiteralPath $runtimePath -Directory -ErrorAction SilentlyContinue|Where-Object{Test-Path -LiteralPath (Join-Path $_.FullName 'msedgewebview2.exe')}).Count -gt 0;if(!$runtimeInstalled){$installer=Join-Path $package 'prerequisites\MicrosoftEdgeWebView2RuntimeInstallerX64.exe';$signature=Get-AuthenticodeSignature -LiteralPath $installer;if($signature.Status -ne 'Valid' -or $signature.SignerCertificate.Subject -notmatch 'O=Microsoft Corporation'){throw '微软运行环境签名验证未通过'};$result=Start-Process -FilePath $installer -ArgumentList '/silent','/install' -WindowStyle Hidden -Wait -PassThru;if($result.ExitCode -ne 0){throw ('运行环境安装未完成，退出码：'+$result.ExitCode)}}
 $client=Join-Path $versionRoot 'app\client';@{serverUrl=$plan.ServerUrl}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $client 'client.json') -Encoding UTF8
 $exe=Join-Path $versionRoot 'app\server\LevelManager.Host.exe';$binary='"'+$exe+'" --data-root "'+$DataRoot+'" --urls "'+$plan.ServerUrl.TrimEnd('/')+'" --ServiceName "'+$ServiceName+'"'
 if($service){$native=Get-CimInstance Win32_Service -Filter ("Name='"+$ServiceName+"'");$changed=Invoke-CimMethod -InputObject $native -MethodName Change -Arguments @{PathName=$binary;StartMode='Automatic'};if($changed.ReturnValue -ne 0){throw '服务升级配置失败，旧版本与数据已保留'}}else{New-Service -Name $ServiceName -BinaryPathName $binary -DisplayName '液位管理系统后台' -StartupType Automatic -Description '液位采集、报警与历史；关闭桌面画面不停止后台。'|Out-Null}
 & sc.exe failure $ServiceName 'reset=' '86400' 'actions=' 'restart/5000/restart/30000/restart/60000'|Out-Null;if($LASTEXITCODE -ne 0){throw '服务恢复策略设置失败'}
 $shell=New-Object -ComObject WScript.Shell;$shortcut=$shell.CreateShortcut((Join-Path ([Environment]::GetFolderPath('CommonDesktopDirectory')) '液位管理系统.lnk'));$shortcut.TargetPath=Join-Path $client 'LevelManager.Desktop.exe';$shortcut.WorkingDirectory=$client;$shortcut.IconLocation=$shortcut.TargetPath+',0';$shortcut.Save();$plan|Add-Member -NotePropertyName VersionRoot -NotePropertyValue $versionRoot;$plan|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $InstallRoot 'installation.json') -Encoding UTF8
 if($businessLock){$businessLock.Dispose();$businessLock=$null};Start-Service -Name $ServiceName;$ready=$false;for($i=0;$i -lt 30;$i++){try{$health=Invoke-RestMethod ($plan.ServerUrl+'api/health') -TimeoutSec 1;if($health.version -eq $manifest.version -and (!$manifest.revision -or ([string]$health.revision).EndsWith('-'+$manifest.revision))){$ready=$true;break}}catch{};Start-Sleep -Seconds 1};if(!$ready){throw '服务尚未就绪。已保留安装与数据，请查看Windows服务和事件日志'}
 $taskFinished=if($service){'r22升级完成。原账号、业务数据与本机授权继续使用。请从标准桌面快捷方式打开，核对侧栏r22、通讯和储罐配置。升级保留原来的只读采集启动策略；不会续跑旧仪表动作。'}else{'r22安装完成。请从桌面打开液位管理系统，建立管理员并按说明导入供方授权。新安装默认不启动采集，请先核对通讯和储罐配置。'};[Windows.Forms.MessageBox]::Show($taskFinished,'液位管理系统','OK','Information')|Out-Null
}catch{if($PrepareOnly){throw};[Windows.Forms.MessageBox]::Show($_.Exception.Message,'安装未完成','OK','Error')|Out-Null;exit 1}finally{if($businessLock){$businessLock.Dispose()}}
